-- public.get_thread_list
begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();

-- Threads: announcement (A), group (G: coach, par1, par3), direct (D: par1 <-> par3)
set local role anon; select set_config('request.jwt.claims', '{"role":"anon"}', true);
select throws_ok($$ select * from public.get_thread_list('e1000000-0000-0000-0000-000000000001') $$, '42501', null, 'anonymous cannot call');
reset role; select set_config('request.jwt.claims', '{"sub":"bb000000-0000-0000-0000-000000000001","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.get_thread_list('e1000000-0000-0000-0000-000000000001')), 3, 'a participant lists announcement, group and direct');
select is((select last_body from public.get_thread_list('e1000000-0000-0000-0000-000000000001') where thread_id='71000000-0000-0000-0000-00000000000b'), 'new group msg', 'last message preview');
select is((select other_name is not null from public.get_thread_list('e1000000-0000-0000-0000-000000000001') where thread_id='71000000-0000-0000-0000-00000000000c'), true, 'direct threads show the other persons name');
select is((select member_count from public.get_thread_list('e1000000-0000-0000-0000-000000000001') where thread_id='71000000-0000-0000-0000-00000000000b'), 3, 'group member count');
select is((select member_count from public.get_thread_list('e1000000-0000-0000-0000-000000000001') where thread_id='71000000-0000-0000-0000-00000000000a'), 7, 'announcement member count is the team');
select public.mark_thread_read('71000000-0000-0000-0000-00000000000a','81000000-0000-0000-0000-000000000004');
select is((select unread_count from public.get_thread_list('e1000000-0000-0000-0000-000000000001') where thread_id='71000000-0000-0000-0000-00000000000a'), 0, 'marking read clears the count');
reset role; select set_config('request.jwt.claims', '{"sub":"bb000000-0000-0000-0000-000000000002","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.get_thread_list('e1000000-0000-0000-0000-000000000001')), 1, 'a non-participant sees only the announcement');
reset role; select set_config('request.jwt.claims', '{"sub":"bb000000-0000-0000-0000-000000000003","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.get_thread_list('e1000000-0000-0000-0000-000000000001') where thread_id='71000000-0000-0000-0000-00000000000b' and last_body='new group msg'), 1, 'a late joiner sees only messages from their join time');
reset role; select set_config('request.jwt.claims', '{"sub":"dd000000-0000-0000-0000-000000000002","role":"authenticated"}', true); set local role authenticated;
select is((select count(*)::int from public.get_thread_list('e1000000-0000-0000-0000-000000000001')), 0, 'another team sees nothing');
reset role; select set_config('request.jwt.claims', '{"sub":"bb000000-0000-0000-0000-000000000001","role":"authenticated"}', true); set local role authenticated;
reset role;
select * from finish();
rollback;
